use std::cmp::Reverse;
use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, Write};
use std::process::ExitCode;

const TOP: usize = 10;

fn is_word_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric()
}

fn count_words(text: &[u8]) -> HashMap<Vec<u8>, u64> {
    let mut counts: HashMap<Vec<u8>, u64> = HashMap::new();
    for word in text.split(|&b| !is_word_byte(b)) {
        if word.is_empty() {
            continue;
        }
        let lower = word.to_ascii_lowercase();
        *counts.entry(lower).or_insert(0) += 1;
    }
    counts
}

fn run(path: &str) -> io::Result<()> {
    let text = fs::read(path)?;
    let counts = count_words(&text);

    let mut entries: Vec<(Vec<u8>, u64)> = counts.into_iter().collect();
    entries.sort_by(|(wa, ca), (wb, cb)| Reverse(ca).cmp(&Reverse(cb)).then_with(|| wa.cmp(wb)));

    let stdout = io::stdout();
    let mut out = stdout.lock();
    for (word, count) in entries.iter().take(TOP) {
        out.write_all(word)?;
        writeln!(out, " {count}")?;
    }
    out.flush()
}

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    let Some(path) = args.get(1) else {
        eprintln!("usage: {} <file>", args.first().map_or("word-frequency", String::as_str));
        return ExitCode::FAILURE;
    };

    match run(path) {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("error: {path}: {err}");
            ExitCode::FAILURE
        }
    }
}

